    // TODO: If val < min_val, val = min_val; if val > max_val, val = max_val
}

lessons.solution_code:
void clamp(double& val, double min_val, double max_val) {
    if (val < min_val) val = min_val;
    else if (val > max_val) val = max_val;
}

